import React, { useCallback } from "react";
import { Link, NavLink, useLocation } from "react-router-dom";
import { LogOut } from "lucide-react";

import { LogoTiles } from "@/components/protocol/LogoTiles";
import { ThemeToggle } from "@/components/ui/ThemeToggle";
import { useWallet } from "@/hooks/useWallet";
import {
  SIDEBAR_SECTIONS,
  TERMINAL_DEFAULT_PATH,
  TERMINAL_NAV,
  TERMINAL_NAV_BY_SLUG,
  type TerminalSectionSlug,
} from "@/constants/terminalNav";
import { useProfileStore } from "@/state/profileStore";
import { useToastStore } from "@/state/toastStore";

const activeLinkClass =
  "flex min-h-[44px] items-center gap-3 rounded-xl bg-white px-3 py-2 font-body text-[15px] font-semibold text-zap-ink shadow-none dark:bg-white/10";

const inactiveLinkClass =
  "flex min-h-[44px] items-center gap-3 rounded-xl px-3 py-2 font-body text-[15px] font-medium text-zap-ink-muted transition-colors hover:bg-[#f5f0eb] hover:text-zap-ink dark:hover:bg-white/[0.06] dark:hover:text-zap-ink";

const logoutLinkClass =
  "flex min-h-[44px] w-full items-center gap-3 rounded-xl px-3 py-2 text-left font-body text-[15px] font-medium text-zap-error transition-colors hover:bg-zap-error-dim/35 hover:text-zap-error dark:hover:bg-zap-error-dim/25";

export interface DashboardSidebarProps {
  mobileOpen: boolean;
  onNavigate: () => void;
}

const DashboardSidebar: React.FC<DashboardSidebarProps> = ({
  mobileOpen,
  onNavigate,
}) => {
  const { pathname } = useLocation();
  const { disconnect } = useWallet();
  const profile = useProfileStore((s) => s.profile);
  const isRegistered = useProfileStore((s) => s.isRegistered);
  const { addToast } = useToastStore();

  const publicPath =
    isRegistered && profile?.username ? `/@${profile.username}` : null;

  const copyShareLink = useCallback(() => {
    if (!publicPath) {
      addToast({
        message:
          "Create your profile first — then your public link will appear here.",
        type: "info",
        duration: 3500,
      });
      return;
    }
    const url = `${window.location.origin}${publicPath}`;
    void navigator.clipboard.writeText(url).then(
      () => {
        addToast({
          message: "Link copied — paste it anywhere your fans are.",
          type: "success",
          duration: 3000,
        });
      },
      () => {
        addToast({
          message: "Couldn’t copy — select the link from your page manually.",
          type: "error",
          duration: 4000,
        });
      },
    );
  }, [addToast, publicPath]);

  const isTerminalActive = (slug: TerminalSectionSlug) => {
    const to = `/terminal/${slug}`;
    return pathname === to || pathname.startsWith(`${to}/`);
  };

  return (
    <>
      {mobileOpen ? (
        <button
          type="button"
          className="fixed inset-0 z-40 bg-black/35 backdrop-blur-[1px] md:hidden"
          aria-label="Close navigation"
          onClick={onNavigate}
        />
      ) : null}

      <aside
        className={[
          "fixed left-0 top-0 z-50 flex h-[100dvh] max-h-[100dvh] w-[min(280px,88vw)] flex-col overflow-hidden border-r border-transparent bg-zap-bg-raised/95 shadow-none backdrop-blur-sm transition-transform duration-200 ease-out",
          "md:bg-transparent md:backdrop-blur-none md:shadow-none",
          "md:static md:z-0 md:h-full md:shrink-0 md:w-[240px] md:min-w-[240px] md:max-h-none md:translate-x-0 md:border-zap-border/35",
          mobileOpen ? "translate-x-0" : "-translate-x-full md:translate-x-0",
        ].join(" ")}
      >
        <div className="flex shrink-0 items-center gap-2 px-4 py-5 md:px-2 md:pt-6">
          <Link
            to={TERMINAL_DEFAULT_PATH}
            className="inline-flex origin-left scale-[0.58] md:scale-[0.62]"
            aria-label="Zap402 home"
          >
            <LogoTiles variant="hero" />
          </Link>
        </div>

        <nav
          className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden overscroll-y-contain px-3 py-3 pr-2"
          aria-label="Workspace"
        >
          {SIDEBAR_SECTIONS.map((section, sectionIdx) => (
            <div
              key={section.title}
              className={
                sectionIdx > 0
                  ? "mt-3 border-t border-[var(--card-border-soft)] pt-3"
                  : ""
              }
            >
              <p className="px-3 pb-2 font-body text-[11px] font-semibold uppercase tracking-[0.06em] text-zap-ink-muted">
                {section.title}
              </p>
              <div className="space-y-0.5">
                {section.slugs?.map((slug) => {
                  const item = TERMINAL_NAV_BY_SLUG[slug];
                  const meta = TERMINAL_NAV.find((n) => n.slug === slug);
                  const to = `/terminal/${item.slug}`;
                  const Icon = item.icon;
                  const active = isTerminalActive(slug);
                  if (meta?.comingSoon) {
                    return (
                      <NavLink
                        key={item.slug}
                        to={to}
                        className={() =>
                          [
                            active ? activeLinkClass : inactiveLinkClass,
                            "flex-wrap gap-x-2 gap-y-1",
                          ].join(" ")
                        }
                        onClick={onNavigate}
                        end={false}
                      >
                        <span className="flex min-w-0 flex-1 items-center gap-3">
                          <Icon
                            size={18}
                            strokeWidth={1.75}
                            className="shrink-0 opacity-80"
                            aria-hidden
                          />
                          <span className="min-w-0">{item.label}</span>
                        </span>
                        <span className="shrink-0 rounded-full bg-zap-accent-dim px-2.5 py-1 font-mono text-[9px] font-bold uppercase tracking-[0.14em] text-zap-accent shadow-sm dark:bg-zap-accent-dim dark:text-zap-accent">
                          Coming soon
                        </span>
                      </NavLink>
                    );
                  }
                  return (
                    <NavLink
                      key={item.slug}
                      to={to}
                      className={() => (active ? activeLinkClass : inactiveLinkClass)}
                      onClick={onNavigate}
                      end={false}
                    >
                      <Icon
                        size={18}
                        strokeWidth={1.75}
                        className="shrink-0 opacity-90"
                        aria-hidden
                      />
                      {item.label}
                    </NavLink>
                  );
                })}
                {section.links?.map((link) => {
                  const Icon = link.icon;
                  const active =
                    pathname === link.to || pathname.startsWith(`${link.to}/`);
                  return (
                    <NavLink
                      key={link.to}
                      to={link.to}
                      className={() => (active ? activeLinkClass : inactiveLinkClass)}
                      onClick={onNavigate}
                      end={link.to === "/network"}
                    >
                      <Icon
                        size={18}
                        strokeWidth={1.75}
                        className="shrink-0 opacity-90"
                        aria-hidden
                      />
                      {link.label}
                    </NavLink>
                  );
                })}
              </div>
              {section.title === "Account" ? (
                <div className="mt-4 space-y-3 border-0 bg-transparent">
                  <div
                    className="h-px w-full bg-transparent dark:bg-transparent"
                    aria-hidden
                  />
                  {/* <button
                    type="button"
                    onClick={copyShareLink}
                    className="w-full border-0 bg-transparent px-0 py-0.5 text-left font-body text-sm font-semibold text-zap-ink shadow-none transition-colors hover:bg-transparent hover:text-zap-brand dark:hover:bg-transparent"
                  >
                    Copy my link
                  </button> */}
                  <div className="flex flex-col gap-1">
                    <button
                      type="button"
                      onClick={() => {
                        disconnect();
                        onNavigate();
                      }}
                      className={logoutLinkClass}
                    >
                      <LogOut
                        size={18}
                        strokeWidth={1.75}
                        className="shrink-0 opacity-90"
                        aria-hidden
                      />
                      Log out
                    </button>
                    <div className="mt-4 border-t border-[var(--card-border-soft)] pt-4 dark:border-zap-border/50">
                      <div className="flex justify-start [&_button]:border-transparent [&_button]:bg-transparent [&_button]:shadow-none [&_button:hover]:border-transparent [&_button:hover]:bg-transparent dark:[&_button]:border-transparent dark:[&_button]:bg-transparent">
                        <ThemeToggle showModeLabel />
                      </div>
                    </div>
                  </div>
                </div>
              ) : null}
            </div>
          ))}
        </nav>
      </aside>
    </>
  );
};

export default DashboardSidebar;
