import type { LucideIcon } from "lucide-react";
import {
  Coins,
  Home,
  Inbox,
  Lock,
  MessageCircle,
  Settings,
  ShoppingBag,
  Users,
} from "lucide-react";

/** URL segment under `/terminal/:section`. */
export type TerminalSectionSlug =
  | "home"
  | "earnings"
  | "content"
  | "ask"
  | "inbox"
  | "purchases"
  | "settings";

export type TerminalNavItem = {
  slug: TerminalSectionSlug;
  tabId: string;
  label: string;
  /** Shorter label for the mobile tab bar */
  shortLabel?: string;
  icon: LucideIcon;
  /** Nav shows label only; tab route still exists for Coming soon panel. */
  comingSoon?: boolean;
};

export const TERMINAL_NAV: readonly TerminalNavItem[] = [
  { slug: "home", tabId: "home", label: "Home", icon: Home },
  { slug: "earnings", tabId: "earnings", label: "Earnings", icon: Coins },
  { slug: "content", tabId: "content", label: "Content", icon: Lock },
  {
    slug: "ask",
    tabId: "ask",
    label: "Ask",
    shortLabel: "Ask",
    icon: MessageCircle,
    comingSoon: true,
  },
  {
    slug: "inbox",
    tabId: "clone",
    label: "Inbox",
    icon: Inbox,
    comingSoon: true,
  },
  {
    slug: "purchases",
    tabId: "purchases",
    label: "My purchases",
    shortLabel: "Purchases",
    icon: ShoppingBag,
  },
  { slug: "settings", tabId: "config", label: "Settings", icon: Settings },
] as const;

/** Ko-fi–style group labels for the left sidebar (subset includes external links). */
export type SidebarSection = {
  title: string;
  /** Terminal slugs in order */
  slugs?: readonly TerminalSectionSlug[];
  /** Routes outside `/terminal/*` */
  links?: readonly {
    to: string;
    label: string;
    icon: LucideIcon;
  }[];
};

export const SIDEBAR_SECTIONS: readonly SidebarSection[] = [
  { title: "Overview", slugs: ["home"] },
  { title: "Earn & sell", slugs: ["earnings", "content"] },
  { title: "Fans & messages", slugs: ["inbox"] },
  { title: "Explore", links: [{ to: "/network", label: "Network", icon: Users }] },
  { title: "Account", slugs: ["purchases", "settings"] },
] as const;

export const TERMINAL_NAV_BY_SLUG: Record<TerminalSectionSlug, TerminalNavItem> =
  Object.fromEntries(TERMINAL_NAV.map((n) => [n.slug, n])) as Record<
    TerminalSectionSlug,
    TerminalNavItem
  >;

const SLUG_TO_TAB = Object.fromEntries(
  TERMINAL_NAV.map((n) => [n.slug, n.tabId]),
) as Record<TerminalSectionSlug, string>;

const TAB_TO_SLUG = Object.fromEntries(
  TERMINAL_NAV.map((n) => [n.tabId, n.slug]),
) as Record<string, TerminalSectionSlug>;

export function terminalSlugToTabId(slug: string | undefined): string {
  if (!slug) return "home";
  const tab = SLUG_TO_TAB[slug as TerminalSectionSlug];
  return tab ?? "home";
}

export function terminalTabIdToSlug(tabId: string): TerminalSectionSlug {
  return TAB_TO_SLUG[tabId] ?? "home";
}

export function isTerminalSectionSlug(s: string): s is TerminalSectionSlug {
  return (TERMINAL_NAV as readonly TerminalNavItem[]).some((n) => n.slug === s);
}

/** Old URLs — redirect to current slugs. */
export const TERMINAL_LEGACY_SLUG_REDIRECT: Record<string, TerminalSectionSlug> = {
  overview: "home",
  tips: "earnings",
  unlocks: "content",
  clone: "inbox",
};

export const TERMINAL_DEFAULT_PATH = "/terminal/home";
