import React, { useEffect, useState } from "react";
import { Navigate, Outlet, useLocation } from "react-router-dom";
import { Menu } from "lucide-react";

import { useWallet } from "@/hooks/useWallet";
import { useProfileStore } from "@/state/profileStore";
import DashboardSidebar from "@/components/layout/DashboardSidebar";
import DashboardMobileNav from "@/components/layout/DashboardMobileNav";
import {
  isOwnCreatorPage,
  isPublicZapPath,
} from "@/utils/dashboardRouteGuards";

/**
 * Creator workspace: left sidebar + main (no top bar). Uses `.editorial-container` so the shell
 * matches landing/editorial max width and centering (see `index.scss`).
 * Public creator URLs: registered + connected users get this full shell (same as Terminal). Unregistered (or not
 * connected) visitors get `<Outlet />` + marketing `Header` from `App`.
 */
const DashboardLayout: React.FC = () => {
  const { connected } = useWallet();
  const { pathname } = useLocation();
  const isRegistered = useProfileStore((s) => s.isRegistered);
  const profile = useProfileStore((s) => s.profile);
  const [mobileNavOpen, setMobileNavOpen] = useState(false);

  const profileOnboarding = pathname === "/profile" && !isRegistered;

  useEffect(() => {
    setMobileNavOpen(false);
  }, [pathname]);

  if (!connected) {
    if (isPublicZapPath(pathname)) {
      return <Outlet />;
    }
    return <Navigate to="/" replace state={{ from: pathname }} />;
  }

  if (profileOnboarding) {
    return <Outlet />;
  }

  if (
    isPublicZapPath(pathname) &&
    !isOwnCreatorPage(pathname, profile?.username) &&
    !isRegistered
  ) {
    return <Outlet />;
  }

  const closeMobile = () => setMobileNavOpen(false);

  const mainScrollClass =
    "min-h-0 flex-1 overflow-y-auto overscroll-y-contain focus:outline-none";

  return (
    <div className="dashboard-shell flex min-h-[100dvh] w-full justify-center overflow-hidden bg-[var(--dashboard-canvas)] text-zap-ink">
      <button
        type="button"
        className="fixed left-3 top-3 z-[55] inline-flex h-11 w-11 items-center justify-center rounded-xl border border-zap-border bg-zap-bg-raised/95 text-zap-ink shadow-sm backdrop-blur-sm md:hidden"
        aria-label="Open navigation menu"
        onClick={() => setMobileNavOpen(true)}
      >
        <Menu size={20} strokeWidth={1.75} aria-hidden />
      </button>
      <div className="editorial-container flex h-[100dvh] min-h-0 w-full flex-row gap-4 md:gap-8">
        <DashboardSidebar
          mobileOpen={mobileNavOpen}
          onNavigate={closeMobile}
        />
        <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden pt-14 md:pt-0">
          <main id="main-content" tabIndex={-1} className={mainScrollClass}>
            <div className="min-h-0 pb-[4.5rem] md:pb-0">
              <Outlet />
            </div>
          </main>
          <DashboardMobileNav />
        </div>
      </div>
    </div>
  );
};

export default DashboardLayout;
