import React from "react";
import { MessageCircle, Twitter } from "lucide-react";
import { Link, useLocation } from "react-router-dom";

import { LogoTiles } from "@/components/protocol/LogoTiles";
import { blogUrl, contractSpecUrl, docsUrl, site } from "@/config/site";
import { env } from "@/config/env";
import { useWallet } from "@/hooks/useWallet";
import { useProfileStore } from "@/state/profileStore";
import { stellarExpertContractUrl } from "@/utils/format";

function contractFooterLine(): { text: string; href: string | null } {
  const id = env.contractId;
  if (!id) {
    return {
      text: "Contract not configured — set VITE_CONTRACT_ID in .env",
      href: null,
    };
  }
  const short = `${id.slice(0, 6)}…${id.slice(-4)}`;
  const isMain = env.network === "MAINNET";
  const netLabel =
    env.network === "MAINNET"
      ? "Mainnet"
      : env.network === "FUTURENET"
        ? "Futurenet"
        : "Testnet";
  return {
    text: `Contract ${short} · ${netLabel}`,
    href: stellarExpertContractUrl(id, isMain ? "PUBLIC" : "TESTNET"),
  };
}

const Footer: React.FC = () => {
  const { pathname } = useLocation();
  const hideNetworkNav = pathname === "/";
  const { connected } = useWallet();
  const profile = useProfileStore((s) => s.profile);
  const isRegistered = useProfileStore((s) => s.isRegistered);

  const profileLinkTo = connected
    ? isRegistered
      ? "/terminal/home"
      : "/profile"
    : "/register";
  const profileLinkLabel =
    connected && (Boolean(profile) || isRegistered) ? "Profile" : "Create profile";

  const link =
    "font-body text-sm text-zap-ink-muted transition-colors hover:text-zap-brand";
  const heading =
    "font-body text-xs font-semibold uppercase tracking-[0.12em] text-zap-ink-faint";

  const contractLine = contractFooterLine();

  return (
    <footer className="border-t border-zap-border bg-zap-bg-raised py-16 text-zap-ink">
      <div className="editorial-container">
        <div className="grid grid-cols-1 gap-10 sm:grid-cols-2 sm:gap-12 lg:grid-cols-4">
          <div className="flex flex-col gap-3 sm:col-span-2 lg:col-span-1">
            <LogoTiles variant="footer" />
            <p className="max-w-sm text-pretty font-body text-sm leading-relaxed text-zap-ink-muted">
              Tips, unlocks, and pay-to-ask — settled in USDC on Stellar, with x402-style flows. Open
              to every wallet.
            </p>
          </div>

          <div className="flex flex-col gap-3">
            <h3 className={heading}>Product</h3>
            <Link to="/" className={link}>
              Home
            </Link>
            {!hideNetworkNav ? (
              <Link to="/network" className={link}>
                Network
              </Link>
            ) : null}
            <Link to="/terminal" className={link}>
              Terminal
            </Link>
            <Link to="/#comparison" className={link}>
              Pricing
            </Link>
            <Link to={profileLinkTo} className={link}>
              {profileLinkLabel}
            </Link>
          </div>

          <div className="flex flex-col gap-3">
            <h3 className={heading}>Developers</h3>
            <a
              href={docsUrl}
              target="_blank"
              rel="noopener noreferrer"
              className={link}
            >
              Docs
            </a>
            <a
              href={site.githubOrgRepo}
              target="_blank"
              rel="noopener noreferrer"
              className={link}
            >
              GitHub
            </a>
            <a
              href={contractSpecUrl}
              target="_blank"
              rel="noopener noreferrer"
              className={link}
            >
              Contract spec
            </a>
            <a
              href={blogUrl}
              target="_blank"
              rel="noopener noreferrer"
              className={link}
            >
              Updates
            </a>
          </div>

          <div className="flex flex-col gap-3">
            <h3 className={heading}>Community</h3>
            <a
              href={site.twitter}
              target="_blank"
              rel="noopener noreferrer"
              className={`flex items-center gap-2 ${link}`}
            >
              <Twitter size={16} className="shrink-0 opacity-90" aria-hidden />
              X / Twitter
            </a>
            <a
              href={site.stellarDiscord}
              target="_blank"
              rel="noopener noreferrer"
              className={`flex items-center gap-2 ${link}`}
            >
              <MessageCircle
                size={16}
                className="shrink-0 opacity-90"
                aria-hidden
              />
              Stellar Discord
            </a>
            <span className={`${link} cursor-default opacity-70`}>Newsletter — soon</span>
          </div>
        </div>

        <div className="mt-12 flex flex-col gap-3 border-t border-zap-border pt-8 sm:mt-14 sm:flex-row sm:items-center sm:justify-between">
          <p className="text-pretty font-body text-xs text-zap-ink-muted">
            © {new Date().getFullYear()} Zap402 · MIT License
          </p>

          {contractLine.href ? (
            <a
              href={contractLine.href}
              target="_blank"
              rel="noopener noreferrer"
              className="font-mono text-[11px] text-zap-ink-faint transition-colors hover:text-zap-brand"
            >
              {contractLine.text}
            </a>
          ) : (
            <span className="font-mono text-[11px] text-zap-ink-faint">
              {contractLine.text}
            </span>
          )}

        </div>
      </div>
    </footer>
  );
};

export default Footer;
