import React, {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react";
import { X } from "lucide-react";
import { useLocation, useNavigate } from "react-router-dom";

import {
  MODAL_FOOTER_CANCEL_CLASS,
  MODAL_ICON_CLOSE_CLASS,
} from "@/components/primitives/Modal";
import { FREIGHTER_ID, XBULL_ID, useWallet } from "@/hooks/useWallet";

const WALLETS: { id: string; name: string; href: string; blurb: string }[] = [
  {
    id: FREIGHTER_ID,
    name: "Freighter",
    href: "https://www.freighter.app/",
    blurb: "Browser extension for Stellar.",
  },
  {
    id: XBULL_ID,
    name: "xBull",
    href: "https://xbull.app/",
    blurb: "Mobile and desktop wallet for Stellar.",
  },
];

/** Don’t send users to /register when they’re already claiming or only connecting to tip a creator. */
function shouldSkipPostConnectRegisterRedirect(pathname: string): boolean {
  if (pathname === "/register") return true;
  if (/^\/@[^/]+$/u.test(pathname)) return true;
  return false;
}

function shouldOfferWalletInstallPage(errorMessage: string | null): boolean {
  const m = (errorMessage ?? "").toLowerCase().trim();
  if (!m) return false;
  const likelyUserCancel =
    m.includes("reject") ||
    m.includes("denied") ||
    m.includes("cancel") ||
    m.includes("closed") ||
    m.includes("dismiss") ||
    (m.includes("user") && m.includes("abort"));

  if (likelyUserCancel) return false;

  const hintsNeedInstall =
    m.includes("not connected") ||
    m.includes("not installed") ||
    m.includes("install freighter") ||
    m.includes("could not establish") ||
    m.includes("could not reach freighter") ||
    m.includes("could not reach xbull") ||
    m.includes("freighter.app") ||
    m.includes("xbull.app") ||
    m.includes("no wallet") ||
    m.includes("unavailable") ||
    (m.includes("freighter") && m.includes("not"));

  return hintsNeedInstall;
}

type WalletConnectModalContextValue = {
  openConnectModal: () => void;
};

const WalletConnectModalContext =
  createContext<WalletConnectModalContextValue | null>(null);

export function useWalletConnectModal(): WalletConnectModalContextValue {
  const ctx = useContext(WalletConnectModalContext);
  if (!ctx) {
    throw new Error(
      "useWalletConnectModal must be used within WalletConnectModalProvider",
    );
  }
  return ctx;
}

/** Prefer the education modal; if the provider is missing, opens the default kit picker. */
export function useOpenWalletConnect(): () => void {
  const ctx = useContext(WalletConnectModalContext);
  const { connect } = useWallet();
  return useCallback(() => {
    if (ctx) ctx.openConnectModal();
    else void connect();
  }, [ctx, connect]);
}

interface WalletEducationModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const WalletEducationModal: React.FC<WalletEducationModalProps> = ({
  isOpen,
  onClose,
}) => {
  const navigate = useNavigate();
  const { pathname } = useLocation();
  const { connectWithWallet, connecting, error } = useWallet();
  const [pendingId, setPendingId] = useState<string | null>(null);

  const handleWallet = async (w: (typeof WALLETS)[number]) => {
    setPendingId(w.id);
    const { ok, errorMessage } = await connectWithWallet(w.id);
    setPendingId(null);

    if (ok) {
      onClose();
      if (!shouldSkipPostConnectRegisterRedirect(pathname)) {
        navigate("/profile");
      }
      return;
    }

    // Do not use window.freighter — modern Freighter often omits it while the
    // extension is installed. Always try connect first; only then offer install.
    if (
      (w.id === FREIGHTER_ID || w.id === XBULL_ID) &&
      shouldOfferWalletInstallPage(errorMessage)
    ) {
      window.open(w.href, "_blank", "noopener,noreferrer");
    }
  };

  if (!isOpen) return null;

  /** Matches marketing header “Sign up free” — solid ink pill, inverted label. */
  const connectWalletBtnClass =
    "inline-flex min-h-[40px] w-full items-center justify-center rounded-full bg-zap-ink px-5 font-body text-base font-semibold text-zap-bg transition-opacity hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zap-brand focus-visible:ring-offset-2 focus-visible:ring-offset-zap-surface disabled:pointer-events-none disabled:opacity-45 sm:w-auto sm:min-w-[7.5rem]";

  return (
    <div className="fixed inset-0 z-[100] flex items-end justify-center font-body sm:items-center">
      <button
        type="button"
        className="absolute inset-0 bg-black/60 backdrop-blur-3xl backdrop-saturate-50 dark:bg-black/75"
        aria-label="Close dialog"
        onClick={onClose}
      />
      <div
        className="relative z-10 flex max-h-[min(100dvh,720px)] w-full flex-col overflow-hidden rounded-t-3xl border border-zap-border bg-zap-surface shadow-none max-sm:max-h-[92dvh] sm:mx-4 sm:max-h-[85vh] sm:max-w-lg sm:rounded-3xl"
        role="dialog"
        aria-modal="true"
        aria-labelledby="wallet-modal-title"
      >
        <div className="flex shrink-0 items-center justify-between gap-4 border-b border-zap-border px-5 py-4 sm:px-8 sm:py-5">
          <h2
            id="wallet-modal-title"
            className="min-w-0 font-body text-xl font-semibold leading-snug tracking-tight text-zap-ink"
          >
            Connect wallet
          </h2>
          <button
            type="button"
            onClick={onClose}
            className={MODAL_ICON_CLOSE_CLASS}
            aria-label="Close"
          >
            <X size={18} strokeWidth={2} aria-hidden />
          </button>
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto px-5 py-5 sm:px-8 sm:py-6">
          <div className="rounded-2xl bg-zap-bg-alt/30 p-5">
            <div className="space-y-4">
              <div>
                <p className="font-mono text-[11px] font-normal uppercase tracking-[0.14em] text-zap-ink-faint">
                  Wallet
                </p>
                <p className="mt-1.5 text-pretty text-sm font-normal leading-relaxed text-zap-ink-muted">
                  Your keys stay in your wallet—you approve each transaction. We never see your secret
                  key.
                </p>
              </div>
              <div className="pt-4">
                <p className="font-mono text-[11px] font-normal uppercase tracking-[0.14em] text-zap-ink-faint">
                  Stellar
                </p>
                <p className="mt-1.5 text-pretty text-sm font-normal leading-relaxed text-zap-ink-muted">
                  Tips and unlocks settle on Stellar in USDC. A small XLM reserve covers network fees
                  only; it isn&apos;t your spending balance.
                </p>
              </div>
            </div>
          </div>

          <ul className="mt-6 flex flex-col gap-3">
            {WALLETS.map((w) => (
              <li key={w.id} className="kofi-dashboard-card p-4 shadow-none transition-colors duration-200 ease-out hover:border-zap-border-bright md:p-5">
                <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between sm:gap-4">
                  <div className="min-w-0">
                    <h3 className="font-body text-lg font-semibold tracking-tight text-zap-ink">
                      {w.name}
                    </h3>
                    <p className="mt-1.5 text-pretty text-sm font-medium leading-relaxed text-zap-ink-muted">
                      {w.blurb}
                    </p>
                  </div>
                  <div className="flex shrink-0 sm:justify-end">
                    <button
                      type="button"
                      disabled={connecting || pendingId === w.id}
                      onClick={() => void handleWallet(w)}
                      className={connectWalletBtnClass}
                      aria-label={`Connect or get ${w.name}`}
                    >
                      {pendingId === w.id ? "Connecting…" : "Connect"}
                    </button>
                  </div>
                </div>
              </li>
            ))}
          </ul>

          {error ? (
            <p className="mt-4 text-pretty text-sm font-medium leading-relaxed text-zap-error" role="alert">
              {error}
            </p>
          ) : null}

        </div>
      </div>
    </div>
  );
};

export function WalletConnectModalProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const value = useMemo(
    () => ({ openConnectModal: () => setOpen(true) }),
    [],
  );

  return (
    <WalletConnectModalContext.Provider value={value}>
      {children}
      <WalletEducationModal isOpen={open} onClose={() => setOpen(false)} />
    </WalletConnectModalContext.Provider>
  );
}
