import React, { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { Link, NavLink, useLocation } from "react-router-dom";

import { useOpenWalletConnect } from "@/components/wallet/WalletConnectModal";
import ChainStatus from "@/components/wallet/ChainStatus";
import { LogoTiles } from "@/components/protocol/LogoTiles";
import { blogUrl } from "@/config/site";
import { TERMINAL_DEFAULT_PATH } from "@/constants/terminalNav";
import { useWallet } from "@/hooks/useWallet";
import { useProfileStore } from "@/state/profileStore";
import { isPublicZapPath } from "@/utils/dashboardRouteGuards";

const navLinkClass = ({ isActive }: { isActive: boolean }): string => {
  const base =
    "font-body text-[11px] font-normal uppercase tracking-[0.15em] transition-colors min-h-[44px] inline-flex items-center";
  if (isActive) {
    return `${base} text-zap-accent`;
  }
  return `${base} text-zap-ink-muted hover:text-zap-ink`;
};

const landingLinkClass =
  "font-body text-base font-medium text-zap-ink-muted transition-colors hover:text-zap-ink min-h-[44px] inline-flex items-center";

const Header: React.FC = () => {
  const { pathname } = useLocation();
  const isLanding = pathname === "/";
  const openConnectModal = useOpenWalletConnect();
  const { connected, publicKey, disconnect } = useWallet();
  const isRegistered = useProfileStore((s) => s.isRegistered);
  const profileHomeHref = isRegistered ? TERMINAL_DEFAULT_PATH : "/profile";
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const headerRef = useRef<HTMLElement>(null);

  /** Same as home: How it works / Blog / Log in when visiting a public creator link logged out. */
  const showLandingMarketingNav =
    isLanding || (isPublicZapPath(pathname) && !connected);
  const howItWorksHref = isLanding ? "#how-it-works" : "/#how-it-works";

  useEffect(() => {
    const handlePointerDown = (event: MouseEvent) => {
      if (
        mobileMenuOpen &&
        headerRef.current &&
        !headerRef.current.contains(event.target as Node)
      ) {
        setMobileMenuOpen(false);
      }
    };

    document.addEventListener("mousedown", handlePointerDown);
    return () => document.removeEventListener("mousedown", handlePointerDown);
  }, [mobileMenuOpen]);

  const closeMobileMenu = () => setMobileMenuOpen(false);

  const handleWalletAction = () => {
    if (connected) disconnect();
    else openConnectModal();
    closeMobileMenu();
  };

  const truncated =
    connected && publicKey
      ? `${publicKey.slice(0, 4)}…${publicKey.slice(-4)}`
      : null;

  const mobileNavClass = ({ isActive }: { isActive: boolean }) => {
    const base =
      "py-2 font-body text-[11px] font-normal uppercase tracking-[0.15em] transition-colors";
    if (isActive) {
      return `${base} text-zap-accent`;
    }
    return `${base} text-zap-ink-muted`;
  };

  return (
    <header
      ref={headerRef}
      className="header-chrome sticky top-0 z-50 min-h-14 border-b border-zap-border"
    >
      <div className="editorial-container flex h-full min-h-14 w-full items-center justify-between gap-3 py-2">
        <div className="flex min-w-0 flex-1 items-center gap-4 md:gap-8">
          <LogoTiles variant="header" />
          {showLandingMarketingNav ? (
            <nav className="hidden items-center gap-6 lg:flex" aria-label="Marketing">
              <a href={howItWorksHref} className={landingLinkClass}>
                How it works
              </a>
              <a
                href={blogUrl}
                target="_blank"
                rel="noopener noreferrer"
                className={landingLinkClass}
              >
                Blog
              </a>
            </nav>
          ) : (
            <nav className="hidden items-center gap-6 md:flex" aria-label="Main">
              <NavLink to="/" className={navLinkClass} end>
                HOME
              </NavLink>
              <NavLink to="/network" className={navLinkClass}>
                NETWORK
              </NavLink>
              <NavLink
                to={TERMINAL_DEFAULT_PATH}
                className={({ isActive }) =>
                  navLinkClass({
                    isActive: isActive || pathname.startsWith("/terminal"),
                  })
                }
              >
                TERMINAL
              </NavLink>
              <NavLink to={profileHomeHref} className={navLinkClass}>
                {isRegistered ? "HOME" : "PROFILE"}
              </NavLink>
            </nav>
          )}
        </div>

        <div className="flex shrink-0 items-center justify-end gap-4 md:gap-5">
          {showLandingMarketingNav ? (
            <>
              <div className="hidden items-center gap-5 sm:flex">
                {connected ? (
                  <>
                    <Link
                      to={TERMINAL_DEFAULT_PATH}
                      className="font-body text-base font-medium text-zap-ink-muted transition-colors hover:text-zap-ink"
                    >
                      Dashboard
                    </Link>
                    <Link
                      to={profileHomeHref}
                      className="inline-flex min-h-[40px] items-center justify-center rounded-full border border-zap-border bg-zap-bg-raised px-5 font-body text-base font-semibold text-zap-ink no-underline transition-opacity hover:opacity-90"
                    >
                      {isRegistered ? "Home" : "Profile"}
                    </Link>
                  </>
                ) : (
                  <>
                    <button
                      type="button"
                      onClick={() => openConnectModal()}
                      className="shrink-0 font-body text-base font-medium text-zap-ink-muted transition-colors hover:text-zap-ink"
                    >
                      Log in
                    </button>
                    <Link
                      to="/register"
                      className="inline-flex min-h-[40px] shrink-0 items-center justify-center rounded-full bg-zap-ink px-5 font-body text-base font-semibold text-zap-bg no-underline transition-opacity hover:opacity-90"
                    >
                      Sign up free
                    </Link>
                  </>
                )}
              </div>
            </>
          ) : (
            <div className="hidden items-center gap-2.5 md:flex">
              <ChainStatus />
              <button
                type="button"
                onClick={connected ? disconnect : openConnectModal}
                className="nav-editorial-cta"
              >
                {truncated ? (
                  <span className="font-body text-[11px] font-normal tracking-normal normal-case text-zap-teal">
                    WALLET · {truncated}
                  </span>
                ) : (
                  "CONNECT WALLET"
                )}
              </button>
            </div>
          )}

          <button
            type="button"
            className="inline-flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-zap-border bg-zap-bg-raised font-body text-lg text-zap-ink lg:hidden"
            aria-label={mobileMenuOpen ? "Close menu" : "Open menu"}
            aria-expanded={mobileMenuOpen}
            onClick={() => setMobileMenuOpen((o) => !o)}
          >
            {mobileMenuOpen ? "×" : "≡"}
          </button>
        </div>
      </div>

      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.2 }}
            className="border-t border-zap-border bg-zap-bg-raised lg:hidden"
          >
            <div className="editorial-container flex flex-col gap-1 py-4">
              {showLandingMarketingNav ? (
                <>
                  <a
                    href={howItWorksHref}
                    className="py-2 font-body text-base font-medium text-zap-ink"
                    onClick={closeMobileMenu}
                  >
                    How it works
                  </a>
                  <a
                    href={blogUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="py-2 font-body text-base font-medium text-zap-ink"
                    onClick={closeMobileMenu}
                  >
                    Blog
                  </a>
                  <div className="mt-3 flex flex-col gap-2 border-t border-zap-border pt-4">
                    {connected ? (
                      <>
                        <Link
                          to={TERMINAL_DEFAULT_PATH}
                          className="py-2 font-body text-base font-medium text-zap-ink"
                          onClick={closeMobileMenu}
                        >
                          Dashboard
                        </Link>
                        <Link
                          to={profileHomeHref}
                          className="inline-flex min-h-[44px] items-center justify-center rounded-full border border-zap-border bg-zap-bg-raised font-body text-base font-semibold text-zap-ink no-underline"
                          onClick={closeMobileMenu}
                        >
                          {isRegistered ? "Home" : "Profile"}
                        </Link>
                      </>
                    ) : (
                      <>
                        <button
                          type="button"
                          onClick={() => {
                            openConnectModal();
                            closeMobileMenu();
                          }}
                          className="py-2 text-left font-body text-base font-medium text-zap-ink-muted"
                        >
                          Log in
                        </button>
                        <Link
                          to="/register"
                          className="inline-flex min-h-[44px] items-center justify-center rounded-full bg-zap-ink font-body text-base font-semibold text-zap-bg no-underline"
                          onClick={closeMobileMenu}
                        >
                          Sign up free
                        </Link>
                      </>
                    )}
                  </div>
                </>
              ) : (
                <>
                  <NavLink to="/" className={mobileNavClass} end onClick={closeMobileMenu}>
                    HOME
                  </NavLink>
                  <NavLink to="/network" className={mobileNavClass} onClick={closeMobileMenu}>
                    NETWORK
                  </NavLink>
                  <NavLink
                    to={TERMINAL_DEFAULT_PATH}
                    className={({ isActive }) =>
                      mobileNavClass({
                        isActive:
                          isActive || pathname.startsWith("/terminal"),
                      })
                    }
                    onClick={closeMobileMenu}
                  >
                    TERMINAL
                  </NavLink>
                  <NavLink to={profileHomeHref} className={mobileNavClass} onClick={closeMobileMenu}>
                    {isRegistered ? "HOME" : "PROFILE"}
                  </NavLink>
                  <div className="mt-3 flex flex-wrap items-center gap-4 border-t border-zap-border pt-4">
                    <ChainStatus />
                    <button
                      type="button"
                      onClick={handleWalletAction}
                      className="nav-editorial-cta min-w-0 flex-1"
                    >
                      <span className="text-zap-teal" aria-hidden>
                        ►
                      </span>
                      {connected && truncated ? (
                        <span className="font-body text-[11px] font-normal tracking-normal normal-case text-zap-teal">
                          WALLET · {truncated}
                        </span>
                      ) : (
                        "Connect Wallet"
                      )}
                    </button>
                  </div>
                </>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
};

export default Header;
